// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedPlanDifferentialSupport.SUBJECT_LOOKUP_COSTS;
import static org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedPlanDifferentialSupport.VF;
import static org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedPlanDifferentialSupport.add;
import static org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedPlanDifferentialSupport.assertPackedPlanPreservesResults;
import static org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedPlanDifferentialSupport.iri;
import static org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedPlanDifferentialSupport.model;
import static org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedPlanDifferentialSupport.parse;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Model;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.junit.jupiter.api.Test;

/**
 * Domain facts of a memo group are derived from the group's seed expression only. Alternatives that logical rules
 * append to a group are consumers of facts, never producers: otherwise a single unsound alternative (here the
 * term-identity finite anchor for a value-equality filter over a non-canonical numeric domain) narrows the facts of
 * every sibling and every enclosing group and lets an unrelated JOIN be proven empty.
 */
class PackedSeedOnlyDomainFactsTest {

	private static final IRI V = iri("v");
	private static final IRI W = iri("w");
	private static final IRI P = iri("p");
	private static final IRI Q = iri("q");

	/** {@code :v} holds {1, 01, 1.0, 2} and {@code :w} holds {1.0}: value-equal, term-distinct numerics. */
	static final PackedPredicateRangeProvider NON_CANONICAL_NUMERIC_PROVIDER = new PackedPredicateRangeProvider() {
		@Override
		public boolean describeObjectRange(IRI predicate, PackedPredicateRange output) {
			if (V.equals(predicate)) {
				output.setState(PackedPredicateRange.STATE_KNOWN);
				output.setKindBits(PackedPredicateRange.KIND_LITERAL);
				output.setLanguageBits(PackedPredicateRange.LANGUAGE_WITHOUT);
				output.addDatatype(CoreDatatype.XSD.INTEGER);
				output.addDatatype(CoreDatatype.XSD.DECIMAL);
				output.setUniversalBits(PackedPredicateRange.UNIVERSAL_NUMBER);
				output.setFinite(true);
				output.addFiniteValue(VF.createLiteral("1", CoreDatatype.XSD.INTEGER));
				output.addFiniteValue(VF.createLiteral("01", CoreDatatype.XSD.INTEGER));
				output.addFiniteValue(VF.createLiteral("1.0", CoreDatatype.XSD.DECIMAL));
				output.addFiniteValue(VF.createLiteral("2", CoreDatatype.XSD.INTEGER));
				return true;
			}
			if (W.equals(predicate)) {
				output.setState(PackedPredicateRange.STATE_KNOWN);
				output.setKindBits(PackedPredicateRange.KIND_LITERAL);
				output.setLanguageBits(PackedPredicateRange.LANGUAGE_WITHOUT);
				output.addDatatype(CoreDatatype.XSD.DECIMAL);
				output.setUniversalBits(PackedPredicateRange.UNIVERSAL_NUMBER);
				output.setFinite(true);
				output.addFiniteValue(VF.createLiteral("1.0", CoreDatatype.XSD.DECIMAL));
				return true;
			}
			return false;
		}

		@Override
		public long predicateRangeVersion() {
			return 11L;
		}
	};

	/** {@code :q} holds only the string {@code "c"}; {@code :p} is unknown. */
	private static final PackedPredicateRangeProvider STRING_C_PROVIDER = new PackedPredicateRangeProvider() {
		@Override
		public boolean describeObjectRange(IRI predicate, PackedPredicateRange output) {
			if (!Q.equals(predicate)) {
				return false;
			}
			output.setState(PackedPredicateRange.STATE_KNOWN);
			output.setKindBits(PackedPredicateRange.KIND_LITERAL);
			output.setLanguageBits(PackedPredicateRange.LANGUAGE_WITHOUT);
			output.addDatatype(CoreDatatype.XSD.STRING);
			output.setFinite(true);
			output.addFiniteValue(VF.createLiteral("c"));
			return true;
		}

		@Override
		public long predicateRangeVersion() {
			return 12L;
		}
	};

	static Model nonCanonicalNumericData() {
		Model data = model();
		add(data, "s1", "v", VF.createLiteral("1", CoreDatatype.XSD.INTEGER));
		add(data, "s2", "v", VF.createLiteral("01", CoreDatatype.XSD.INTEGER));
		add(data, "s3", "v", VF.createLiteral("1.0", CoreDatatype.XSD.DECIMAL));
		add(data, "s4", "v", VF.createLiteral("2", CoreDatatype.XSD.INTEGER));
		add(data, "t1", "w", VF.createLiteral("1.0", CoreDatatype.XSD.DECIMAL));
		return data;
	}

	// ------------------------------------------------------------------ poisoning through an appended alternative

	@Test
	void anchorAlternativeDoesNotProveEnclosingJoinEmpty() {
		PackedQuery packed = PackedQueryCodec.encodeForPlanning(
				parse("SELECT ?s ?t WHERE { ?s :v ?o FILTER(?o = 1) ?t :w ?o }"), NON_CANONICAL_NUMERIC_PROVIDER);

		assertEquals(Set.of(), predicateRangeEmptyGroups(packed),
				"the FILTER group's facts must stay those of its seed (the :v range); an appended anchor alternative "
						+ "must not narrow them to {1} and prove the JOIN with :w = {1.0} empty");
	}

	@Test
	void anchorAlternativeDoesNotProveEnclosingJoinEmptyThroughNestedGroup() {
		PackedQuery packed = PackedQueryCodec.encodeForPlanning(
				parse("SELECT ?s ?t WHERE { { ?s :v ?o FILTER(?o = 1) } ?t :w ?o }"),
				NON_CANONICAL_NUMERIC_PROVIDER);

		assertEquals(Set.of(), predicateRangeEmptyGroups(packed));
	}

	@Test
	void anchorAlternativeDoesNotPoisonSiblingFilterVerdict() {
		PackedQuery packed = PackedQueryCodec.encodeForPlanning(
				parse("SELECT ?s WHERE { ?s :v ?o FILTER(?o = 1) FILTER(datatype(?o) = xsd:decimal) }"),
				NON_CANONICAL_NUMERIC_PROVIDER);

		assertEquals(Set.of(), predicateRangeEmptyGroups(packed),
				"the datatype filter must see the seed's {integer, decimal} range, not the anchor's {integer}");
	}

	// ------------------------------------------------------------------ sound narrowing still comes from the seed

	@Test
	void termIdentitySafeFilterConstantsStillProveDisjointJoinEmpty() {
		PackedQuery packed = PackedQueryCodec.encodeForPlanning(
				parse("SELECT ?s ?t WHERE { ?s :p ?o FILTER(?o IN (\"a\", \"b\")) ?t :q ?o }"), STRING_C_PROVIDER);

		assertFalse(predicateRangeEmptyGroups(packed).isEmpty(),
				"{\"a\",\"b\"} joined with the stored :q domain {\"c\"} by term identity is empty; the FILTER seed "
						+ "itself must contribute its finite string domain");
		Model data = model();
		add(data, "s1", "p", VF.createLiteral("a"));
		add(data, "t1", "q", VF.createLiteral("c"));
		assertPackedPlanPreservesResults(data, "SELECT ?s ?t WHERE { ?s :p ?o FILTER(?o IN (\"a\", \"b\")) ?t :q ?o }",
				SUBJECT_LOOKUP_COSTS, STRING_C_PROVIDER, List.of());
	}

	@Test
	void termIdentitySafeFilterConstantsKeepOverlappingJoin() {
		PackedQuery packed = PackedQueryCodec.encodeForPlanning(
				parse("SELECT ?s ?t WHERE { ?s :p ?o FILTER(?o IN (\"a\", \"c\")) ?t :q ?o }"), STRING_C_PROVIDER);

		assertTrue(predicateRangeEmptyGroups(packed).isEmpty(), "\"c\" is in both domains");
		Model data = model();
		add(data, "s1", "p", VF.createLiteral("a"));
		add(data, "s2", "p", VF.createLiteral("c"));
		add(data, "t1", "q", VF.createLiteral("c"));
		assertPackedPlanPreservesResults(data, "SELECT ?s ?t WHERE { ?s :p ?o FILTER(?o IN (\"a\", \"c\")) ?t :q ?o }",
				SUBJECT_LOOKUP_COSTS, STRING_C_PROVIDER, List.of("s=urn:t:s2|t=urn:t:t1"));
	}

	@Test
	void numericFilterConstantsDoNotNarrowSeedFacts() {
		PackedQuery packed = PackedQueryCodec.encodeForPlanning(
				parse("SELECT ?s ?t WHERE { ?s :p ?o FILTER(?o IN (1, 2)) ?t :w ?o }"), NON_CANONICAL_NUMERIC_PROVIDER);

		assertEquals(Set.of(), predicateRangeEmptyGroups(packed),
				"numeric constants are not term-identity safe: 1 value-equals the stored 1.0, so no emptiness proof");
		Model data = model();
		add(data, "s1", "p", VF.createLiteral("1.0", CoreDatatype.XSD.DECIMAL));
		add(data, "t1", "w", VF.createLiteral("1.0", CoreDatatype.XSD.DECIMAL));
		assertPackedPlanPreservesResults(data, "SELECT ?s ?t WHERE { ?s :p ?o FILTER(?o IN (1, 2)) ?t :w ?o }",
				SUBJECT_LOOKUP_COSTS, NON_CANONICAL_NUMERIC_PROVIDER, List.of("s=urn:t:s1|t=urn:t:t1"));
	}

	// ------------------------------------------------------------------ helpers

	static Set<Integer> predicateRangeEmptyGroups(PackedQuery query) {
		Set<Integer> groups = new LinkedHashSet<>();
		for (int relationId = 1; relationId <= query.relationCount(); relationId++) {
			if (query.relOperator(relationId) == PackedRelOp.EMPTY_SET
					&& (query.relRuleMask(relationId) & PackedRuleProofs.PREDICATE_RANGE_EMPTY) != 0L) {
				groups.add(query.relGroup(relationId));
			}
		}
		return Set.copyOf(groups);
	}
}
